<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  overflow: hidden;
  font-family: 'Segoe UI', Ubuntu, Cantarell, sans-serif;
  user-select: none;
}

#desktop {
  width: 100vw;
  height: 100vh;
  background: linear-gradient(135deg, #2c001e 0%, #4a0033 25%, #77216f 50%, #5e2750 75%, #2c001e 100%);
  position: relative;
  display: flex;
  flex-direction: column;
}

/* Top Bar */
#topbar {
  height: 28px;
  background: rgba(0, 0, 0, 0.85);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  color: #fff;
  font-size: 13px;
  z-index: 10000;
  flex-shrink: 0;
}

#topbar .topbar-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

#topbar .topbar-right {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
}

/* Taskbar / Dock */
#taskbar {
  position: absolute;
  left: 0;
  top: 28px;
  bottom: 0;
  width: 56px;
  background: rgba(0, 0, 0, 0.75);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 12px;
  gap: 8px;
  z-index: 9000;
}

.launcher-btn {
  width: 44px;
  height: 44px;
  border-radius: 8px;
  border: none;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  transition: background 0.2s;
}

.launcher-btn:hover {
  background: rgba(255, 255, 255, 0.18);
}

.launcher-btn:active {
  background: rgba(255, 255, 255, 0.25);
}

/* Desktop area */
#desktop-area {
  flex: 1;
  position: relative;
  margin-left: 56px;
}

/* Windows */
.window {
  position: absolute;
  background: #2d2d2d;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6), 0 2px 8px rgba(0, 0, 0, 0.4);
  display: none;
  flex-direction: column;
  overflow: hidden;
  min-width: 360px;
  min-height: 240px;
  z-index: 100;
}

.window.active {
  z-index: 200;
}

.window-header {
  height: 38px;
  background: #1e1e1e;
  display: flex;
  align-items: center;
  padding: 0 12px;
  flex-shrink: 0;
  border-bottom: 1px solid #3a3a3a;
}

.window-title {
  color: #ddd;
  font-size: 13px;
  font-weight: 500;
  flex: 1;
  text-align: center;
}

.win-close {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: none;
  background: #e95420;
  color: #fff;
  cursor: pointer;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}

.win-close:hover {
  background: #c7411a;
}

.window-body {
  flex: 1;
  overflow: auto;
  color: #e0e0e0;
}

/* Files App */
#files-window {
  width: 600px;
  height: 420px;
  top: 60px;
  left: 120px;
}

#files-toolbar {
  display: flex;
  align-items: center;
  padding: 8px 12px;
  background: #353535;
  border-bottom: 1px solid #444;
  gap: 8px;
}

#files-up {
  padding: 4px 12px;
  background: #4a4a4a;
  border: 1px solid #555;
  border-radius: 4px;
  color: #e0e0e0;
  cursor: pointer;
  font-size: 13px;
}

#files-up:hover {
  background: #555;
}

#files-path {
  flex: 1;
  padding: 4px 10px;
  background: #2a2a2a;
  border: 1px solid #444;
  border-radius: 4px;
  color: #e0e0e0;
  font-size: 13px;
  font-family: monospace;
}

#files-listing {
  padding: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-content: flex-start;
}

.fs-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 90px;
  padding: 8px 4px;
  border-radius: 6px;
  cursor: pointer;
  text-align: center;
  transition: background 0.15s;
}

.fs-item:hover {
  background: rgba(255, 255, 255, 0.08);
}

.fs-item .fs-icon {
  font-size: 32px;
  margin-bottom: 4px;
}

.fs-item .fs-name {
  font-size: 12px;
  color: #e0e0e0;
  word-break: break-word;
  line-height: 1.3;
}

/* Notepad App */
#notepad-window {
  width: 560px;
  height: 400px;
  top: 80px;
  left: 200px;
}

#tabs {
  display: flex;
  background: #1e1e1e;
  border-bottom: 1px solid #444;
  align-items: flex-end;
  padding: 0 4px;
  min-height: 34px;
  flex-shrink: 0;
}

.tab {
  padding: 6px 16px;
  background: #2d2d2d;
  color: #aaa;
  border: 1px solid #444;
  border-bottom: none;
  border-radius: 6px 6px 0 0;
  cursor: pointer;
  font-size: 12px;
  margin-right: 2px;
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 150px;
  transition: background 0.15s;
}

.tab:hover {
  background: #383838;
}

.tab.active {
  background: #353535;
  color: #fff;
  border-color: #555;
}

.tab .tab-close {
  font-size: 14px;
  color: #888;
  cursor: pointer;
  line-height: 1;
}

.tab .tab-close:hover {
  color: #e95420;
}

#new-tab {
  padding: 4px 10px;
  background: transparent;
  border: 1px solid #555;
  border-radius: 4px;
  color: #aaa;
  cursor: pointer;
  font-size: 16px;
  margin-left: 4px;
  margin-bottom: 2px;
  transition: background 0.15s;
}

#new-tab:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

#editor {
  width: 100%;
  flex: 1;
  background: #1e1e1e;
  color: #e0e0e0;
  border: none;
  padding: 12px;
  font-family: 'Courier New', monospace;
  font-size: 14px;
  line-height: 1.5;
  resize: none;
  outline: none;
}

#editor::placeholder {
  color: #666;
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #2d2d2d;
}

::-webkit-scrollbar-thumb {
  background: #555;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #666;
}
</style>
</head>
<body>
<div id="desktop">
  <!-- Top Bar -->
  <div id="topbar">
    <div class="topbar-left">
      <span>Activities</span>
      <span id="topbar-app-name"></span>
    </div>
    <div class="topbar-right">
      <span id="clock"></span>
    </div>
  </div>

  <!-- Taskbar / Dock -->
  <div id="taskbar">
    <button class="launcher-btn" id="open-files" title="Files">📁</button>
    <button class="launcher-btn" id="open-notepad" title="Text Editor">📝</button>
  </div>

  <!-- Desktop Area -->
  <div id="desktop-area">
    <!-- Files Window -->
    <div class="window" id="files-window">
      <div class="window-header">
        <span class="window-title">Files</span>
        <button class="win-close" data-target="files-window">✕</button>
      </div>
      <div class="window-body" style="display:flex;flex-direction:column;">
        <div id="files-toolbar">
          <button id="files-up">⬆ Up</button>
          <span id="files-path">/</span>
        </div>
        <div id="files-listing"></div>
      </div>
    </div>

    <!-- Notepad Window -->
    <div class="window" id="notepad-window">
      <div class="window-header">
        <span class="window-title">Text Editor</span>
        <button class="win-close" data-target="notepad-window">✕</button>
      </div>
      <div class="window-body" style="display:flex;flex-direction:column;">
        <div id="tabs">
          <button id="new-tab">+</button>
        </div>
        <textarea id="editor" placeholder="Start typing..."></textarea>
      </div>
    </div>
  </div>
</div>

<script>
// ============ CLOCK ============
function updateClock() {
  const now = new Date();
  const opts = { weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' };
  document.getElementById('clock').textContent = now.toLocaleDateString('en-US', opts);
}
updateClock();
setInterval(updateClock, 1000);

// ============ FILESYSTEM DATA ============
const filesystem = {
  '/': {
    type: 'dir',
    children: ['bin', 'etc', 'home', 'usr', 'var']
  },
  '/bin': {
    type: 'dir',
    children: ['bash', 'ls', 'cp', 'mv', 'cat', 'grep']
  },
  '/bin/bash': { type: 'file' },
  '/bin/ls': { type: 'file' },
  '/bin/cp': { type: 'file' },
  '/bin/mv': { type: 'file' },
  '/bin/cat': { type: 'file' },
  '/bin/grep': { type: 'file' },
  '/etc': {
    type: 'dir',
    children: ['hosts', 'passwd', 'fstab', 'resolv.conf']
  },
  '/etc/hosts': { type: 'file' },
  '/etc/passwd': { type: 'file' },
  '/etc/fstab': { type: 'file' },
  '/etc/resolv.conf': { type: 'file' },
  '/home': {
    type: 'dir',
    children: ['user']
  },
  '/home/user': {
    type: 'dir',
    children: ['Documents', 'Downloads', 'Pictures', 'notes.txt', '.bashrc']
  },
  '/home/user/Documents': {
    type: 'dir',
    children: ['readme.txt', 'report.pdf', 'todo.md']
  },
  '/home/user/Documents/readme.txt': { type: 'file' },
  '/home/user/Documents/report.pdf': { type: 'file' },
  '/home/user/Documents/todo.md': { type: 'file' },
  '/home/user/Downloads': {
    type: 'dir',
    children: ['image.png', 'archive.tar.gz', 'setup.deb']
  },
  '/home/user/Downloads/image.png': { type: 'file' },
  '/home/user/Downloads/archive.tar.gz': { type: 'file' },
  '/home/user/Downloads/setup.deb': { type: 'file' },
  '/home/user/Pictures': {
    type: 'dir',
    children: ['vacation.jpg', 'screenshot.png', 'wallpaper.jpg']
  },
  '/home/user/Pictures/vacation.jpg': { type: 'file' },
  '/home/user/Pictures/screenshot.png': { type: 'file' },
  '/home/user/Pictures/wallpaper.jpg': { type: 'file' },
  '/home/user/notes.txt': { type: 'file' },
  '/home/user/.bashrc': { type: 'file' },
  '/usr': {
    type: 'dir',
    children: ['bin', 'lib', 'share', 'local']
  },
  '/usr/bin': {
    type: 'dir',
    children: ['python3', 'gcc', 'make', 'vim']
  },
  '/usr/bin/python3': { type: 'file' },
  '/usr/bin/gcc': { type: 'file' },
  '/usr/bin/make': { type: 'file' },
  '/usr/bin/vim': { type: 'file' },
  '/usr/lib': {
    type: 'dir',
    children: ['libstdc++.so', 'libpython3.so']
  },
  '/usr/lib/libstdc++.so': { type: 'file' },
  '/usr/lib/libpython3.so': { type: 'file' },
  '/usr/share': {
    type: 'dir',
    children: ['applications', 'icons', 'man']
  },
  '/usr/share/applications': { type: 'dir', children: [] },
  '/usr/share/icons': { type: 'dir', children: [] },
  '/usr/share/man': { type: 'dir', children: [] },
  '/usr/local': {
    type: 'dir',
    children: ['bin', 'lib']
  },
  '/usr/local/bin': { type: 'dir', children: [] },
  '/usr/local/lib': { type: 'dir', children: [] },
  '/var': {
    type: 'dir',
    children: ['log', 'tmp', 'cache', 'www']
  },
  '/var/log': {
    type: 'dir',
    children: ['syslog', 'auth.log', 'kern.log']
  },
  '/var/log/syslog': { type: 'file' },
  '/var/log/auth.log': { type: 'file' },
  '/var/log/kern.log': { type: 'file' },
  '/var/tmp': { type: 'dir', children: [] },
  '/var/cache': { type: 'dir', children: [] },
  '/var/www': {
    type: 'dir',
    children: ['html']
  },
  '/var/www/html': {
    type: 'dir',
    children: ['index.html']
  },
  '/var/www/html/index.html': { type: 'file' }
};

// ============ FILES APP ============
let currentPath = '/';

function getIcon(name, entry) {
  if (entry && entry.type === 'dir') return '📁';
  const ext = name.split('.').pop().toLowerCase();
  const icons = {
    'txt': '📄', 'md': '📄', 'pdf': '📕',
    'png': '🖼️', 'jpg': '🖼️', 'jpeg': '🖼️',
    'tar.gz': '📦', 'gz': '📦', 'deb': '📦',
    'html': '🌐', 'so': '⚙️', 'log': '📋',
    'conf': '⚙️', 'bash': '⚙️', 'sh': '⚙️'
  };
  return icons[ext] || '📄';
}

function navigateTo(path) {
  const entry = filesystem[path];
  if (!entry || entry.type !== 'dir') return;
  currentPath = path;
  document.getElementById('files-path').textContent = path;
  renderListing();
}

function renderListing() {
  const listing = document.getElementById('files-listing');
  listing.innerHTML = '';
  const entry = filesystem[currentPath];
  if (!entry || !entry.children) return;

  entry.children.forEach(name => {
    const childPath = currentPath === '/' ? '/' + name : currentPath + '/' + name;
    const childEntry = filesystem[childPath];
    const item = document.createElement('div');
    item.className = 'fs-item';
    item.innerHTML = `<span class="fs-icon">${getIcon(name, childEntry)}</span><span class="fs-name">${name}</span>`;
    item.addEventListener('dblclick', () => {
      if (childEntry && childEntry.type === 'dir') {
        navigateTo(childPath);
      }
    });
    listing.appendChild(item);
  });
}

document.getElementById('files-up').addEventListener('click', () => {
  if (currentPath === '/') return;
  const parts = currentPath.split('/').filter(Boolean);
  parts.pop();
  const parent = '/' + parts.join('/');
  navigateTo(parent === '//' ? '/' : parent || '/');
});

// ============ NOTEPAD APP ============
let tabs = [];
let activeTabIndex = -1;

function loadTabs() {
  try {
    const saved = localStorage.getItem('notepad-tabs');
    if (saved) {
      const data = JSON.parse(saved);
      tabs = data.tabs || [];
      activeTabIndex = data.activeIndex || 0;
      if (tabs.length === 0) {
        createTab('Untitled', '', false);
        activeTabIndex = 0;
      }
      if (activeTabIndex >= tabs.length) activeTabIndex = 0;
    } else {
      createTab('Untitled', '', false);
      activeTabIndex = 0;
    }
  } catch (e) {
    tabs = [];
    createTab('Untitled', '', false);
    activeTabIndex = 0;
  }
}

function saveTabs() {
  localStorage.setItem('notepad-tabs', JSON.stringify({
    tabs: tabs,
    activeIndex: activeTabIndex
  }));
}

function createTab(name, content, setActive) {
  const tab = { name: name || 'Untitled', content: content || '' };
  tabs.push(tab);
  if (setActive !== false) {
    activeTabIndex = tabs.length - 1;
  }
  saveTabs();
  renderTabs();
}

function renderTabs() {
  const tabsContainer = document.getElementById('tabs');
  // Remove all tab elements but keep #new-tab
  const existingTabs = tabsContainer.querySelectorAll('.tab');
  existingTabs.forEach(t => t.remove());

  const newTabBtn = document.getElementById('new-tab');

  tabs.forEach((tab, index) => {
    const tabEl = document.createElement('div');
    tabEl.className = 'tab' + (index === activeTabIndex ? ' active' : '');
    tabEl.innerHTML = `<span class="tab-name">${escapeHtml(tab.name)}</span><span class="tab-close" data-index="${index}">✕</span>`;
    tabEl.addEventListener('click', (e) => {
      if (e.target.classList.contains('tab-close')) return;
      switchToTab(index);
    });
    tabEl.querySelector('.tab-close').addEventListener('click', (e) => {
      e.stopPropagation();
      closeTab(index);
    });
    tabsContainer.insertBefore(tabEl, newTabBtn);
  });

  updateEditor();
}

function switchToTab(index) {
  // Save current content first
  if (activeTabIndex >= 0 && activeTabIndex < tabs.length) {
    tabs[activeTabIndex].content = document.getElementById('editor').value;
  }
  activeTabIndex = index;
  saveTabs();
  renderTabs();
}

function closeTab(index) {
  tabs.splice(index, 1);
  if (tabs.length === 0) {
    createTab('Untitled', '', true);
    activeTabIndex = 0;
  } else {
    if (activeTabIndex >= tabs.length) {
      activeTabIndex = tabs.length - 1;
    } else if (activeTabIndex > index) {
      activeTabIndex--;
    } else if (activeTabIndex === index) {
      if (activeTabIndex >= tabs.length) activeTabIndex = tabs.length - 1;
    }
  }
  saveTabs();
  renderTabs();
}

function updateEditor() {
  const editor = document.getElementById('editor');
  if (activeTabIndex >= 0 && activeTabIndex < tabs.length) {
    editor.value = tabs[activeTabIndex].content;
  } else {
    editor.value = '';
  }
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

document.getElementById('new-tab').addEventListener('click', () => {
  // Save current content
  if (activeTabIndex >= 0 && activeTabIndex < tabs.length) {
    tabs[activeTabIndex].content = document.getElementById('editor').value;
  }
  createTab('Untitled', '', true);
});

document.getElementById('editor').addEventListener('input', () => {
  if (activeTabIndex >= 0 && activeTabIndex < tabs.length) {
    tabs[activeTabIndex].content = document.getElementById('editor').value;
    saveTabs();
  }
});

// ============ WINDOW MANAGEMENT ============
function showWindow(id) {
  const win = document.getElementById(id);
  win.style.display = 'flex';
  // Bring to front
  document.querySelectorAll('.window').forEach(w => w.classList.remove('active'));
  win.classList.add('active');
}

function hideWindow(id) {
  const win = document.getElementById(id);
  win.style.display = 'none';
  win.classList.remove('active');
}

document.getElementById('open-files').addEventListener('click', () => {
  showWindow('files-window');
  navigateTo(currentPath);
});

document.getElementById('open-notepad').addEventListener('click', () => {
  showWindow('notepad-window');
  renderTabs();
});

document.querySelectorAll('.win-close').forEach(btn => {
  btn.addEventListener('click', (e) => {
    const target = e.currentTarget.getAttribute('data-target');
    hideWindow(target);
  });
});

// Click on window header to bring to front
document.querySelectorAll('.window').forEach(win => {
  win.addEventListener('mousedown', () => {
    document.querySelectorAll('.window').forEach(w => w.classList.remove('active'));
    win.classList.add('active');
  });
});

// ============ INIT ============
loadTabs();
navigateTo('/');
</script>
</body>
</html>
